Translate("deDE", "stormwind-city", {
	title = "Stormwind",
	aliases = { "Stadt Stormwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Stormwind ist die {link:capital-city}Hauptstadt{/link} des {link:kingdom-of-stormwind}Königreichs Stormwind{/link} und die größte Stadt der {link:humans}Menschen{/link}, die im Süden noch steht. Ihre weißen Mauern erheben sich am westlichen Rand des {link:elwynn-forest}Waldes von Elwynn{/link}, und blaue Kanäle fließen zwischen ihren Vierteln. Händler drängen sich im {link:trade-district}Handelsdistrikt{/link}. Pilger steigen die Stufen der {link:cathedral-of-light}Kathedrale des Lichts{/link} hinauf. Über allen steht die {link:stormwind-keep}Burg Stormwind{/link}, wo die Könige des Reiches seit Generationen herrschen. Die Stadt ist stolz, reich und voller Menschen. Sie ist auch eine Stadt ohne ihren König.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem Stormwind gegründet wurde. Seine Wurzeln liegen bei den Familien von {link:arathor}Arathor{/link}, die vor langer Zeit nach Süden zogen und ein Königreich errichteten, das sie {link:azeroth}Azeroth{/link} nannten. Stormwind war sein Herz. Jahrhundertelang wuchs die Stadt in Frieden, und die Kirche des {link:holy-light}Heiligen Lichts{/link} machte sie zu einem der großen Sitze ihres Glaubens. Dann kam der {link:first-war}Erste Krieg{/link}. Die orcische {link:horde}Horde{/link} brannte das Königreich nieder und plünderte die {link:capital-city}Hauptstadt{/link}, und König {link:llane-wrynn}Llane Wrynn{/link} starb in seiner eigenen Burg. Die Überlebenden flohen mit Sir {link:anduin-lothar}Anduin Lothar{/link} nach Norden nach {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Stormwind wurde nach dem {link:second-war}Zweiten Krieg{/link} Stein um Stein von der {link:stonemasons-guild}Steinmetzgilde{/link} wieder errichtet. Als das {link:house-of-nobles}Haus der Adligen{/link} sich weigerte, diese Arbeit zu bezahlen, erhoben sich die Steinmetze, Königin {link:tiffin-wrynn}Tiffin Wrynn{/link} wurde getötet, und die Steinmetze wurden vertrieben. Sie wurden zur {link:defias-brotherhood}Bruderschaft der Defias{/link}.

Nun ist König {link:varian-wrynn}Varian Wrynn{/link} auf einer diplomatischen Reise verschwunden, und niemand bei Hofe kann sagen, wo er ist. Sein junger Sohn {link:anduin-wrynn}Anduin{/link} trägt den Titel des Königs. Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link} regiert als Regent in seinem Namen, und die Adlige {link:katrana-prestor}Katrana Prestor{/link} ist oft an seiner Seite. Die Armee ist weit fort. Die Defias machen die Straßen vor den Mauern unsicher. Innerhalb der Mauern haben sich die Gefangenen des Verlieses gegen ihre Wachen erhoben. Die Agenten von {link:si-7}SI:7{/link} vermuten, dass jemand bei Hofe der Bruderschaft hilft.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Das Volk von Stormwind.{/b} Händler, Handwerker, Seeleute, Schreiber und die Flüchtlinge der Kriege.
• {b}Der Hof und die Adligen.{/b} Der Regent, seine Ratgeber und die Lords des Hauses der Adligen versammeln sich in der {link:stormwind-keep}Burg Stormwind{/link}.
• {b}Die Geistlichkeit.{/b} Die Priester und Paladine der {link:cathedral-of-light}Kathedrale des Lichts{/link} dienen unter {link:archbishop-benedictus}Erzbischof Benedictus{/link}.
• {b}Die {link:dwarves}Zwerge{/link} von Ironforge.{/b} Sie haben ihr eigenes Viertel an den Stadtmauern, mit seinen Schmieden und dem Tunnel nach {link:ironforge}Ironforge{/link}.
• {b}Die Magier.{/b} Die Zauberer des Magierviertels studieren und lehren in Sichtweite der Burg.
• {b}Verborgenes Volk.{/b} {link:si-7}SI:7{/link} wirkt aus den Schatten der {link:old-town}Altstadt{/link}. Hexenmeister versammeln sich im Keller einer Taverne, und wenige fragen, was sie dort tun.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das alte Königreich.{/b} Jahrhundertelang war Stormwind die {link:capital-city}Hauptstadt{/link} eines friedlichen Reiches, beherrscht vom Haus Wrynn.
• {b}Der Fall.{/b} Im Ersten Krieg durchbrach die {link:horde}Horde{/link} die Stadt. {link:llane-wrynn}Llane{/link} wurde erschlagen, und sein Sohn {link:varian-wrynn}Varian{/link} wurde ins Exil gebracht.
• {b}Der Wiederaufbau.{/b} Nach dem Zweiten Krieg kehrten die Verbannten heim, und die Steinmetze bauten die Stadt auf ihren alten Fundamenten wieder auf.
• {b}Der Aufstand.{/b} Die Adligen wollten die Steinmetze nicht bezahlen. Der Streit endete in Blut und im Tod der Königin.
• {b}Die Gegenwart.{/b} Der König ist verschwunden. Ein Kind sitzt auf dem Thron, ein Regent regiert, und die Feinde des Königreichs werden im eigenen Land kühn.]=],
		},
		{
			title = "Legenden der Stadt",
			text = [=[• Das neue Stormwind wurde auf den Ruinen des alten erbaut. Viele der Männer, die seine Mauern errichteten, verbergen sich heute unter den {link:defias-brotherhood}Defias{/link}.
• Ein Käsehändler im {link:trade-district}Handelsdistrikt{/link} ist nicht nur ein Käsehändler. Wer weiß, welche Tür er nehmen muss, sagt, dass {link:si-7}SI:7{/link} von seinem Laden aus ein Auge auf die Stadt hat.
• Schiffe segeln nun von einem neuen Hafen am Westufer der Stadt über das Meer nach {link:auberdine}Auberdine{/link} an der {link:darkshore}Dunkelküste{/link}.]=],
		},
	},
})

Translate("deDE", "trade-district", {
	title = "Handelsdistrikt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Handelsdistrikt ist das geschäftigste Viertel von {link:stormwind-city}Stormwind{/link}. In seinen Straßen liegen die Bank, das Auktionshaus, das Gasthaus namens Gilded Rose und Läden jedes Handwerks. {link:morgan-pestle}Morgan Pestle{/link} verkauft hier seine Tränke, und die Familie {link:elling-trias}Trias{/link} verkauft Käse. Greifen landen am Rand des Viertels und bringen Briefe und Reisende aus dem ganzen Königreich. Unter allem Feilschen fließt der älteste Handel der Stadt, und das ist das Gerücht. Was man am Mittag im Handelsdistrikt hört, weiß man am Abend in der Burg.]=],
		},
	},
})

Translate("deDE", "cathedral-square", {
	title = "Kathedralenplatz",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kathedralenplatz ist der große offene Platz im Herzen von {link:stormwind-city}Stormwind{/link}. An seinem nördlichen Ende erhebt sich die {link:cathedral-of-light}Kathedrale des Lichts{/link}, das größte Haus des Heiligen Lichts im Süden. Um den Platz stehen das Rathaus, in dem der Architekt {link:baros-alexston}Baros Alexston{/link} sein Amtszimmer hat, und die Hallen, in denen die Geistlichen und Paladine der Stadt ausgebildet werden. Soldaten exerzieren auf den Steinplatten. Pilger kommen, um zu beten. Der Platz ist der Ort, an dem sich Stormwind so zeigt, wie es gesehen werden will: gläubig, geordnet und stark.]=],
		},
	},
})

Translate("deDE", "old-town", {
	title = "Altstadt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Altstadt liegt im Osten von {link:stormwind-city}Stormwind{/link}, wo die Straßen eng und die Gebäude älter sind als anderswo. Sie beherbergt die Kaserne der Stadt und einen Rüstungsladen für Soldaten. Sie ist auch die Heimat von {link:si-7}SI:7{/link}. {link:master-mathias-shaw}Meister Mathias Shaw{/link} arbeitet von der Kaserne aus, und seine Agenten kommen und gehen durch Türen, die die meisten Bürger nie bemerken. In den Gassen kümmern sich die Leute um ihre eigenen Angelegenheiten und stellen wenige Fragen. Soldaten, die neu in der {link:capital-city}Hauptstadt{/link} eintreffen, kommen zuerst hierher, um bewaffnet, untergebracht und dorthin geschickt zu werden, wo das Königreich sie braucht.]=],
		},
	},
})

Translate("deDE", "dwarven-district", {
	title = "Zwergendistrikt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Zwergendistrikt liegt im Norden von {link:stormwind-city}Stormwind{/link}, an den Stadtmauern. Die {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link}, die in Stormwind leben, halten dieses Viertel als ihr eigenes. Hier sind die lautesten Schmieden der Stadt, eine Halle der {link:explorers-league}Forscherliga{/link} und der Eingang zur {red:deeprun-tram}Tiefenbahn{/red}, die unter den Bergen nach Ironforge führt. Das Viertel ist ein Zeichen der alten Freundschaft zwischen den beiden Königreichen. Seine Schmiede sagen, und nicht leise, dass der beste Stahl in Stormwind in ihrer Straße gemacht wird.]=],
		},
	},
})

Translate("deDE", "mage-quarter", {
	title = "Magierviertel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Magierviertel liegt im Südwesten von {link:stormwind-city}Stormwind{/link}, wo violette Dächer über den Kanälen aufragen. In seinem Herzen steht das Wizard's Sanctum, und dort bilden die Magier der Stadt ihre Schüler in der {link:arcane-magic}arkanen Magie{/link} aus. Nicht alle Magie hier ist rechtmäßig. Unter der Taverne namens Slaughtered Lamb treffen sich Hexenmeister in einem Keller und studieren Mächte, die die Kirche verdammt. Nahe dem Viertel, an den Kanälen, steht das finstere Tor des {link:the-stockade}Verlieses{/link}, wo die Wachen von ihren eigenen Gefangenen bis an die Tür zurückgedrängt wurden.]=],
		},
	},
})

Translate("deDE", "the-park", {
	title = "Der Park",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Park ist ein grünes Viertel im Nordwesten von {link:stormwind-city}Stormwind{/link}. Alte Bäume stehen zwischen stillen Wegen. Er ist der ruhigste Ort in einer überfüllten Stadt, und er liegt dicht unter den Mauern der {link:stormwind-keep}Burg Stormwind{/link}. Die Stadtbewohner kommen hierher, um zu ruhen, zu spazieren und zu reden. Roy Lewells führt in der Nähe einen Buchclub. Seine Mitglieder treffen sich nach Feierabend in einem Keller, um über Geschichte und Ideen zu streiten, mit Büchern aus der Königlichen Bibliothek und mit Erfrischungen, die Roy gern mit denen teilt, die ihm helfen.]=],
		},
	},
})

Translate("deDE", "stormwind-keep", {
	title = "Burg Stormwind",
	aliases = { "Schloss Stormwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Burg Stormwind steht am nördlichen Ende der Stadt, der Sitz der Könige aus dem Haus Wrynn. Ihr Thronsaal wird Tag und Nacht bewacht. Dort sitzt der junge {link:anduin-wrynn}König Anduin{/link} neben {link:bolvar-fordragon}Hochlord Bolvar Fordragon{/link}, und {link:katrana-prestor}Lady Katrana Prestor{/link} steht ihnen beiden zu Diensten. Die Burg beherbergt auch die {link:royal-library}Königliche Bibliothek{/link}, die Amtsstuben der Stadtwache und einen ummauerten Garten, in dem die Lords des Hofes lustwandeln. Nicht jedes Gespräch in diesem Garten ist für treue Ohren bestimmt.]=],
		},
	},
})

Translate("deDE", "stormwind-harbor", {
	title = "Hafen von Stormwind",
	aliases = { "Hafen Stormwinds" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im Hafen von Stormwind herrscht wieder reges Treiben. Ein neues Schiff überquert nun von seinem südlichen Anleger aus das Meer nach {link:auberdine}Auberdine{/link} an den Ufern der {link:darkshore}Dunkelküste{/link}, und es bringt Vorräte, Briefe und Reisende zwischen dem Königreich und den Ländern der {link:night-elves}Nachtelfen{/link}. Schreiber zählen die Fracht Kiste um Kiste, und es gibt nie genug Hafenarbeiter. Wachen und Kanoniere beobachten das Wasser. Händler der Stadt haben bereits Verwandte über das Wasser geschickt, um in Auberdine Handel zu treiben, und Briefe kommen in die andere Richtung zurück und bitten um Hilfe. Zum ersten Mal seit Jahren blickt die Stadt über das Meer hinaus.]=],
		},
	},
})

Translate("deDE", "valley-of-heroes", {
	title = "Das Tal der Helden",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Tal der Helden ist der prächtige Zugang zu {link:stormwind-city}Stormwind{/link}. Die Straße aus dem {link:elwynn-forest}Wald von Elwynn{/link} überquert eine lange Brücke und führt zwischen hohen Statuen hindurch, bevor sie das Haupttor der Stadt erreicht. Jeder Reisende, der auf dem Landweg nach Stormwind kommt, geht unter ihnen hindurch. Die Stadtwache hält hier strenge Wacht, denn das Tor ist die erste Verteidigung der {link:capital-city}Hauptstadt{/link} und das Erste, was ihre Besucher sehen. Boten der fernen Marschälle des Königreichs treffen hier ein, und Knappen tragen ihre Nachrichten vom Tor zum Thronsaal.]=],
		},
	},
})

Translate("deDE", "cathedral-of-light", {
	title = "Kathedrale des Lichts",
	aliases = { "Kathedrale des Heiligen Lichts" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kathedrale des Lichts ist das größte Haus des {link:holy-light}Heiligen Lichts{/link} im {link:kingdom-of-stormwind}Königreich Stormwind{/link}. Sie erhebt sich über dem {link:cathedral-square}Kathedralenplatz{/link} im Herzen der Stadt. {link:archbishop-benedictus}Erzbischof Benedictus{/link} führt die Kirche aus ihren Hallen. Priester unterweisen dort die Gläubigen, und in ihren Seitenkammern bildet {link:grayson-shadowbreaker}Lord Grayson Shadowbreaker{/link} die Paladine des Reiches aus.]=],
		},
		{
			title = "Eine Hüterin von Reliquien",
			text = [=[Die Kathedrale tut mehr als beten. Heilige Dinge werden hierher gebracht, um sicher verwahrt zu werden, und verfluchte Dinge werden hierher gebracht, um gereinigt zu werden. Als das verfluchte Auge von Paleth geborgen wurde, trug man es zum Erzbischof. Als im {link:wetlands}Sumpfland{/link} eine kleine Statue von König {link:terenas-menethil}Terenas Menethil{/link} gefunden wurde, schien sich das Licht um sie zu sammeln, und auch sie wurde zur Verwahrung in die Kathedrale gesandt. Die Gläubigen von {link:stormwind-city}Stormwind{/link} vertrauen darauf, dass gut bewacht wird, was die Kathedrale betritt.]=],
		},
		{
			title = "Die Diener der Kathedrale",
			text = [=[Die Kathedrale ist die Heimat von mehr als nur ihrem Erzbischof. Bischöfe, Brüder und Akolythen dienen in ihren Hallen. Bruder Kristoff bereitet dort seine Predigten mit Büchern aus der Königlichen Bibliothek vor, und die Paladine von Lord {link:captain-grayson}Grayson{/link} üben innerhalb ihrer Mauern. Das Wort der Kirche geht von hier aus zur {link:northshire-abbey}Abtei von Nordhain{/link} und zu jeder Kapelle des Reiches.]=],
		},
	},
})

Translate("deDE", "royal-library", {
	title = "Königliche Bibliothek",
	aliases = { "Bibliothek von Stormwind", "Bibliothek Stormwinds" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Königliche Bibliothek liegt in der {link:stormwind-keep}Burg Stormwind{/link}. Sie bewahrt das geschriebene Gedächtnis des Königreichs: Geschichtswerke, Abhandlungen und die Akten des Hofes. Ihr Hüter, {link:milton-sheaf}Milton Sheaf{/link}, lässt nach verlorenen Büchern suchen, wo immer man sie vermutet, vom {link:duskwood}Dämmerwald{/link} bis zu den verlorenen Bibliotheken des gefallenen {link:alterac-mountains}Alterac{/link}.]=],
		},
		{
			title = "Das Verleihen von Büchern",
			text = [=[Die Bibliothek hält ihre Regale nicht nur für Lords bereit. Sie verleiht Bücher an Gelehrte und Geistliche, und in diesen Tagen tauscht sie auch Bände mit einem kleinen Buchclub der Stadt. Die Titel, nach denen dieser Club fragt, verraten, worüber das einfache Volk nun nachdenkt: Berichte über die Raubzüge der {link:horde}Horde{/link}, die Eroberungen der Könige aus dem Haus Trollbane und noch seltsamere Titel.]=],
		},
		{
			title = "Die Bibliothekare",
			text = [=[{link:milton-sheaf}Milton Sheaf{/link} hütet die Bibliothek, und Donyal Tovald wacht über ihre Regale und ihren Verleih. Sie sind genaue Männer. Von einem Buch, das die Bibliothek verlässt, wird erwartet, dass es im selben Zustand zurückkommt, und ein Entleiher, der einen Band mit Achtung behandelt, darf wieder entleihen, wie herausfordernd dessen Worte auch sein mögen.]=],
		},
	},
})

Translate("deDE", "varian-wrynn", {
	title = "Varian Wrynn",
	subtitle = "Der verschwundene König von Stormwind",
	found = "Nirgends; der König ist verschwunden",
	hint = "Erfahrt von dem König, den Stormwind verloren hat.",
	allegiance = "Königreich Stormwind · Haus Wrynn",
	aliases = { "Varian", "König Varian", "König Varian Wrynn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Varian Wrynn ist der König von {link:stormwind-city}Stormwind{/link}, Sohn von König {link:llane-wrynn}Llane Wrynn{/link} und Vater des jungen Anduin. Als Knabe sah er das Königreich seines Vaters brennen, wuchs im Exil zum Mann heran und kehrte heim, um über eine aus ihrer Asche wiedererbaute Stadt zu herrschen. Nun ist er fort. Er brach zu einer diplomatischen Reise auf und kehrte nie zurück, und keine Nachricht von ihm hat seinen Hof erreicht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Varians Abwesenheit prägt ganz {link:stormwind-city}Stormwind{/link}. Ein Kind trägt seinen Titel. Ein Regent regiert in seinem Namen. Seine Armee ist weit fort, seine Straßen sind unsicher, und seine Adligen streiten in den Hallen der Burg. Jeder treue Untertan des Königreichs stellt dieselbe Frage, und niemand bei Hofe kann sie beantworten: Wo ist der König? Bis er zurückkehrt, muss Stormwind von jenen gehalten werden, die an seinem Thron standen.]=],
		},
		{
			title = "Taten",
			text = [=[• Als Knabe überlebte er den Fall von {link:stormwind-city}Stormwind{/link} im {link:first-war}Ersten Krieg{/link}, als sein Vater erschlagen wurde.
• Er wurde von Sir {link:anduin-lothar}Anduin Lothar{/link} nach Norden nach {link:lordaeron}Lordaeron{/link} gebracht und wuchs im Exil auf.
• Nach dem {link:second-war}Zweiten Krieg{/link} kehrte er zurück, um den Thron eines wiedererbauten Stormwind zu besteigen.
• Er heiratete {link:tiffin-wrynn}Tiffin Wrynn{/link} und verlor sie im Aufstand der Steinmetze.
• Er brach zu einer diplomatischen Mission auf und verschwand.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet das Jahr von Varians Verschwinden oder wo er zuletzt gesehen wurde. Was aus ihm geworden ist, weiß man in {link:stormwind-city}Stormwind{/link} nicht.]=],
		},
	},
	chapters = {
		{
			title = "Die Rückkehr des Verbannten",
			hint = "Erfahrt, wie Stormwind wieder aufgebaut wurde.",
			text = [=[Der Knabe, der aus der brennenden Stadt floh, kehrte als Mann heim. {link:stormwind-city}Stormwind{/link} war von den Steinmetzen wieder aufgebaut worden, und Varian wurde in den Hallen seines Vaters gekrönt. Er nahm eine Königin, {link:tiffin-wrynn}Tiffin{/link}, und sie gebar ihm einen Sohn, den er nach dem Helden benannte, der sein Leben gerettet hatte. Eine Zeit lang schien es, als sei das Haus Wrynn durch das Feuer gegangen.]=],
		},
		{
			title = "Der Tod der Königin",
			hint = "Erfahrt, was der Aufstand der Steinmetze den König kostete.",
			text = [=[Als das {link:house-of-nobles}Haus der Adligen{/link} sich weigerte, die {link:stonemasons-guild}Steinmetzgilde{/link} zu bezahlen, erhoben sich die Steinmetze im Zorn. Im Chaos dieses Aufstands wurde {link:tiffin-wrynn}Königin Tiffin{/link} getötet. Die Steinmetze wurden aus der Stadt verstoßen, und der König musste seinen Sohn allein großziehen. Aus dem Exil der Steinmetze wurde die {link:defias-brotherhood}Bruderschaft der Defias{/link} geboren.]=],
		},
		{
			title = "Der leere Thron",
			hint = [=[Bringt dem König einen Bericht über die Bruderschaft der Defias.]=],
			text = [=[Der Bericht war für die Hände des Königs selbst bestimmt. Er erzählte von VanCleefs Bruderschaft und von dem Verrat, der am Hof aufgedeckt worden war. Doch der König war nicht da, um ihn zu lesen. {link:katrana-prestor}Lady Prestor{/link} nahm ihn an seiner Stelle entgegen und sagte nur, Varian sei auf einer diplomatischen Mission. Wohin er gegangen war, sagte sie nicht.]=],
		},
	},
	mentions = {
		{ text = "An Audience with the King, ein an ihn gerichteter Bericht" },
	},
	bonds = {
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "sein Sohn" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "sein Vater" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "seine Königin, im Aufstand verloren" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "brachte ihn ins Exil" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "regiert in seinem Namen" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "spricht in seiner Abwesenheit für den Hof" },
	},
})

Translate("deDE", "anduin-wrynn", {
	title = "Anduin Wrynn",
	subtitle = "Der Kindkönig von Stormwind",
	found = "Der Thronsaal der Burg Stormwind",
	hint = "Sucht eine Audienz im Thronsaal der Burg Stormwind.",
	allegiance = "Königreich Stormwind · Haus Wrynn",
	aliases = { "König Anduin", "Prinz Anduin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Anduin Wrynn ist der einzige Sohn von {link:varian-wrynn}König Varian{/link} und {link:tiffin-wrynn}Königin Tiffin{/link}. Er ist noch ein Kind, und doch trägt er, da sein Vater fort ist, den Titel des Königs von {link:stormwind-city}Stormwind{/link}. Er steht im Thronsaal der Burg zwischen erwachsenen Männern in Rüstung und Damen des Hofes, während {link:bolvar-fordragon}Hochlord Bolvar Fordragon{/link} in seinem Namen regiert.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Anduin ist die Zukunft des Hauses Wrynn und die lebendige Hoffnung seines Königreichs. Solange er im Thronsaal steht, kann das Volk von {link:stormwind-city}Stormwind{/link} glauben, dass die Linie seiner Könige ungebrochen ist. Er wurde nach Sir {link:anduin-lothar}Anduin Lothar{/link} benannt, dem Streiter, der seinen Vater als Knaben rettete und ihn aus der brennenden Stadt trug.

Die Stellung des Knaben ist eine seltsame. Er trägt den höchsten Titel des Reiches, und doch werden die Entscheidungen des Reiches von anderen getroffen. Jeder Bittsteller, der den Thronsaal betritt, verneigt sich vor ihm. Wenige sprechen mit ihm. Sie sprechen mit dem Regenten an seiner Seite und mit der Dame des Hofes, die nahe bei ihnen beiden steht. Anduin sieht und hört alles davon.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verlor seine Mutter im Aufstand der Steinmetze, als er noch sehr jung war.
• Er trägt den Titel seines Vaters, solange der König verschwunden ist.
• Er hält Hof an der Seite des Regenten und der Lords des Königreichs.
• Er wartet im Thronsaal seines Vaters auf Nachricht von seinem Vater.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet das Jahr von Anduins Geburt oder sein genaues Alter in diesen Tagen. Die Akten des Hofes sagen wenig über seine eigenen Gedanken.]=],
		},
	},
	chapters = {
		{
			title = "Ein Kind auf dem Thron",
			hint = "Sprecht mit dem jungen König in der Burg Stormwind.",
			text = [=[Der Knabe hat gelernt, in langen Audienzen still zu stehen. Er hört Marschällen und Adligen zu, Bittschriften von den Höfen und Berichten von den Grenzen. Er hat eine Mutter verloren und vielleicht einen Vater. Der Hof nennt ihn König. Wer genau hinsieht, erkennt, dass er auch ein Kind ist, das auf Nachrichten wartet, die nie kommen.]=],
		},
		{
			title = "Erbe zweier Häuser",
			hint = "Erfahrt die Geschichte des Hauses Wrynn.",
			text = [=[Anduins Großvater, König {link:llane-wrynn}Llane Wrynn{/link}, starb beim Fall des alten {link:stormwind-city}Stormwind{/link}. Sein Vater wuchs im Exil am Hof von {link:terenas-menethil}König Terenas{/link} in {link:lordaeron}Lordaeron{/link} auf und kehrte zurück, um eine neue Stadt zu bauen. Seine Mutter, Königin {link:tiffin-wrynn}Tiffin{/link}, starb in ihren Straßen. Anduin hat sowohl die Krone als auch ihre Wunden geerbt.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "sein Vater, verschwunden" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "seine Mutter" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "sein Regent und Beschützer" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "eine Dame seines Hofes" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "der Held, nach dem er benannt wurde" },
	},
})

Translate("deDE", "bolvar-fordragon", {
	title = "Bolvar Fordragon",
	subtitle = "Regent von Stormwind",
	found = "Der Thronsaal der Burg Stormwind",
	hint = "Sucht den Hochlord auf, der aus dem Thronsaal regiert.",
	allegiance = "Königreich Stormwind · Heiliges Licht",
	aliases = { "Bolvar", "Hochlord Bolvar Fordragon", "Hochlord Fordragon", "Fordragon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hochlord Bolvar Fordragon ist ein Streiter des {link:holy-light}Heiligen Lichts{/link} und der Regent von {link:stormwind-city}Stormwind{/link}. Da {link:varian-wrynn}König Varian{/link} verschwunden und sein Sohn noch ein Kind ist, regiert Bolvar das Königreich aus dem Thronsaal der Burg. Er steht in glänzender Rüstung neben dem jungen Anduin, und jeder Befehl, der die {link:stormwind-keep}Burg Stormwind{/link} verlässt, verlässt sie unter seinem Siegel.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Bolvar hält das Reich in seiner ungewissesten Stunde zusammen. Er muss die Hilferufe jeder bedrängten Grenze beantworten, vom {link:redridge-mountains}Rotkammgebirge{/link} bis zum {link:wetlands}Sumpfland{/link}, mit einer Armee, die schon jetzt zu dünn verteilt ist. Er stützt sich auf den Rat derer um ihn. Unter ihnen wird niemand öfter gehört als {link:katrana-prestor}Lady Katrana Prestor{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er regiert {link:stormwind-city}Stormwind{/link} als Regent im Namen des Kindkönigs.
• Er beschützt Anduin persönlich im Thronsaal der Burg.
• Er empfängt die Bittschriften der Städte und Marschälle des Königreichs.
• Er schickt Streiter gegen Bedrohungen, die die Armee nicht erreichen kann.]=],
		},
	},
	chapters = {
		{
			title = "Der Hilferuf von Seenhain",
			hint = [=[Überbringt dem Regenten den Hilferuf des Friedensrichters von Seenhain.]=],
			text = [=[Friedensrichter {link:magistrate-solomon}Solomon{/link} von {link:lakeshire}Seenhain{/link} schrieb dem Regenten von den Gefahren, die sich um das {link:redridge-mountains}Rotkammgebirge{/link} schlossen, und er flehte die Krone um Hilfe an. Bolvar wollte nicht allein entscheiden. Er schickte den Boten zuerst zu {link:katrana-prestor}Lady Prestor{/link}, und erst nach ihrem Rat setzte er seinen Erlass für Seenhain auf.]=],
		},
		{
			title = "Eine Statue des alten Königs",
			hint = [=[Bringt dem Regenten eine Reliquie von König Terenas aus dem Sumpfland.]=],
			text = [=[Aus dem Hafen von Menethil im {link:wetlands}Sumpfland{/link} kam eine kleine Statue von König {link:terenas-menethil}Terenas Menethil{/link}, geborgen nach langer Suche. Die Hüter des Hafens fürchteten, sie in einem von Feinden bedrängten Land zu behalten. Sie schickten sie geradewegs zu Bolvar, im Vertrauen darauf, dass er wüsste, wo ein solches Andenken an Lordaerons König verwahrt werden sollte.]=],
		},
		{
			title = "Der Waldläuferlord",
			hint = "Bringt dem Regenten Nachricht von Nathanos Marris.",
			text = [=[Zur Burg drang Kunde von {link:nathanos-blightcaller}Nathanos Marris{/link}, einst ein Waldläuferlord, der nun den Verlassenen als Nathanos Blightcaller dient. Bolvar nahm es nicht als Kleinigkeit. Er rief nach einer Armee, die in die {link:eastern-plaguelands}Östlichen Pestländer{/link} marschieren und dem Blightcaller ein Ende setzen sollte, und er warnte, dass die {link:horde}Horde{/link} den Waldläuferlord mit ihrem Leben verteidigen würde.]=],
		},
		{
			title = "Die große Maskerade",
			hint = [=[Steht dem Hochlord bei, wenn die Wahrheit in seinem eigenen Thronsaal enthüllt wird.]=],
			text = [=[Marschall {red:reginald-windsor}Reginald Windsor{/red} kam mit dem Beweis einer Verschwörung im Herzen des Hofes in den Thronsaal. Als er sprach, zeigte die Frau, die Bolvar so lange beraten hatte, ihre wahre Gestalt. Sie war {link:onyxia}Onyxia{/link}, die Tochter von {link:deathwing}Todesschwinge{/link}. Bolvar war ihre Marionette gewesen, und sie sagte es ihm ins Gesicht. Windsor fiel, und der Drache floh. Was sie zurückließ, war ein erschütterter Regent und ein Hof, der den Seinen nicht mehr trauen konnte.]=],
		},
	},
	mentions = {
		{ text = "The True Masters" },
		{ text = "The True Masters" },
		{ text = "A Friend of the Family" },
		{ text = "The First and the Last" },
		{ text = "The {link:nathanos-blightcaller}Blightcaller{/link} Cometh" },
		{ text = "Order Must Be Restored" },
		{ text = "The Great Masquerade" },
		{ text = "The Dragon's Eye" },
	},
	bonds = {
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "der Kindkönig, den er beschützt" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "der König, dem er dient" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "seine vertrauteste Ratgeberin" },
		{ id = "master-mathias-shaw", name = "Meister Mathias Shaw", note = "sein Meisterspion" },
		{ id = "major-samuelson", name = "Major Samuelson", note = "ein Offizier seiner Wache" },
	},
})

Translate("deDE", "katrana-prestor", {
	title = "Katrana Prestor",
	subtitle = "Dame des Hofes von Stormwind",
	found = "Der Thronsaal der Burg Stormwind",
	hint = "Sucht die Adlige auf, die neben dem Regenten steht.",
	allegiance = "Königreich Stormwind · Der Hof",
	aliases = { "Katrana", "Lady Katrana Prestor", "Lady Prestor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lady Katrana Prestor ist eine Adlige von großem Einfluss. Sie steht im Thronsaal der {link:stormwind-keep}Burg Stormwind{/link} neben {link:bolvar-fordragon}Hochlord Bolvar Fordragon{/link}, und sie spricht für den Hof, wenn der Hof sprechen muss. Bittsteller, die zur Burg kommen, stellen oft fest, dass ihre Worte den Regenten erst erreichen, nachdem sie sie erreicht haben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[An einem Hof ohne König hat {link:shadow-council}der Rat{/link} einer vertrauten Beraterin das Gewicht eines Gesetzes. Lady Prestors Stimme wird in jeder großen Frage des Reiches gehört: was das Königreich entbehren kann, wem es glauben soll und welche seiner Sorgen man ohne Gefahr übergehen kann. Manche im Königreich bewundern ihre Weisheit. Andere, fern der {link:capital-city}Hauptstadt{/link}, haben begonnen sich zu fragen, warum ihre Hilferufe so selten eine Antwort finden.

Sie ist immer zugegen. Wenn der Regent eine Bittschrift empfängt, ist sie an seiner Seite. Wenn ein Bericht für den abwesenden König kommt, ist sie es, die ihn entgegennimmt. Wenn der Regent entscheiden muss, bittet er zuerst um ihren Rat. Kein Lord des Hauses der Adligen hat einen so nahen Platz im Herzen des Königreichs.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie berät den Regenten in den Angelegenheiten des Königreichs.
• Sie nimmt Berichte entgegen, die an den abwesenden König gerichtet sind.
• Sie sagt allen, die fragen, dass der König auf einer diplomatischen Mission ist.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Akte des Hofes sagt, woher Lady Prestor kam oder wann sie zuerst in der {link:stormwind-keep}Burg Stormwind{/link} eintraf.]=],
		},
	},
	chapters = {
		{
			title = "Der Bericht für den König",
			hint = [=[Bringt dem König einen Bericht über die Bruderschaft der Defias.]=],
			text = [=[Der Bericht war an {link:varian-wrynn}König Varian{/link} gerichtet. Er erzählte von den {link:defias-brotherhood}Defias{/link}, vom Verrat Lord {link:gregor-agamand}Gregor{/link} Lescovars und vom Meuchelmörder im königlichen Garten. Lady Prestor nahm ihn selbst entgegen. Sie dankte seinem Überbringer und erklärte, der König sei auf einer diplomatischen Mission.]=],
		},
		{
			title = "Rat für den Regenten",
			hint = "Tragt den Hilferuf von Seenhain zur Burg Stormwind.",
			text = [=[Als {link:lakeshire}Seenhain{/link} die Krone um Hilfe im {link:redridge-mountains}Rotkammgebirge{/link} anflehte, wollte der Regent nicht antworten, bevor Lady Prestor gesprochen hatte. Sie hörte den Hilferuf an und gab ihren Rat. Erst dann schrieb {link:bolvar-fordragon}Bolvar{/link} seinen Erlass.]=],
		},
		{
			title = "Die große Maskerade",
			hint = "Seht den Hof von Stormwind, wie er wirklich ist.",
			text = [=[Als Marschall {red:reginald-windsor}Reginald Windsor{/red} mit seinem Beweis in den Thronsaal kam, verspottete Lady Prestor ihn und ließ ihn festnehmen. Dann warf sie ihre Verkleidung ab. Lady Katrana Prestor war nie eine Adlige gewesen. Sie war {link:onyxia}Onyxia{/link}, die Tochter von {link:deathwing}Todesschwinge{/link}, ein schwarzer Drache, der am Hof von {link:stormwind-city}Stormwind{/link} ein menschliches Gesicht getragen hatte. Solange sie neben dem Regenten stand, hatte der schwarze Drachenschwarm das Ohr des Königreichs. Windsor starb im Thronsaal. Onyxia floh, und sie überließ es {link:bolvar-fordragon}Bolvar{/link} zu erkennen, wie lange er ihre Marionette gewesen war.]=],
		},
	},
	mentions = {
		{ text = "An Audience with the King" },
		{ text = "The True Masters" },
		{ text = "The Great Masquerade" },
	},
	bonds = {
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "der Regent, den sie berät" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "der Kindkönig ihres Hofes" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "der König, von dem sie sagt, er sei fort" },
	},
})

Translate("deDE", "archbishop-benedictus", {
	title = "Erzbischof Benedictus",
	subtitle = "Erzbischof der Kirche des Heiligen Lichts",
	found = "Die Kathedrale des Lichts, Kathedralenplatz",
	hint = [=[Sucht das Oberhaupt der Gläubigen in der Kathedrale des Lichts.]=],
	allegiance = "Kirche des Heiligen Lichts · Kathedrale des Lichts",
	aliases = { "Benedictus" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erzbischof Benedictus führt die Kirche des {link:holy-light}Heiligen Lichts{/link} von der {link:cathedral-of-light}Kathedrale des Lichts{/link} in {link:stormwind-city}Stormwind{/link} aus. Er ist das geistliche Oberhaupt der Priester des Königreichs und die Stimme seines Glaubens. Die Geistlichen von {link:northshire-abbey}Nordhain{/link}, die Paladine der Kathedrale und die Bischöfe des Reiches blicken alle zu ihm auf.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Benedictus bekleidet das Amt, das einst {link:alonsus-faol}Alonsus Faol{/link} innehatte, der Erzbischof, der nach dem Ersten Krieg den Orden der Paladine gründete. In einem Zeitalter der Seuche, des Krieges und der dunklen Magie muss der Erzbischof sowohl den Glauben von {link:stormwind-city}Stormwind{/link} als auch die Länder jenseits davon verteidigen. Er betet nicht nur gegen das Böse. Er schickt Streiter, um es zu vernichten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt die Geistlichen der {link:cathedral-of-light}Kathedrale des Lichts{/link}.
• Er nimmt verfluchte Reliquien auf, damit das Licht sie reinigen kann.
• Er schickt Streiter gegen die Diener des Todes jenseits der Grenzen des Königreichs.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Benedictus' Leben geschrieben, bevor er die Mitra des Erzbischofs annahm.]=],
		},
	},
	chapters = {
		{
			title = "Das verfluchte Auge",
			hint = [=[Bringt dem Erzbischof eine Reliquie, die der Reinigung bedarf.]=],
			text = [=[Aus dem {link:wetlands}Sumpfland{/link} kam das Auge von Paleth, eine von einem Fluch verzerrte Reliquie. Es wurde nicht dort zerstört, wo man es fand. Es wurde nach {link:stormwind-city}Stormwind{/link} getragen und in die Hände des Erzbischofs gelegt, denn es gibt wenige im Königreich, die so etwas reinigen könnten.]=],
		},
		{
			title = "Der Kältebringer",
			hint = [=[Folgt dem Ruf des Erzbischofs gegen den Lich der Hügel von Razorfen.]=],
			text = [=[Weit im Süden in {link:kalimdor}Kalimdor{/link}, in den dornigen Hallen der {link:quilboar}Stacheleber{/link}, hat sich ein untotes Wesen namens {link:amnennar-the-coldbringer}Amnennar der Kältebringer{/link} eingenistet. Benedictus wartet nicht, bis solches Übel das Meer überquert. Er bittet um Streiter, die den Kältebringer aufsuchen und ihm im Namen des Lichts ein Ende setzen.]=],
		},
	},
	mentions = {
		{ text = "Cleansing the Eye" },
		{ text = "Bring the Light" },
	},
	bonds = {
		{ id = "grayson-shadowbreaker", name = "Grayson Shadowbreaker", note = "führt die Paladine seiner Kathedrale" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "hatte das Amt vor ihm inne" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "der Regent seines Königreichs" },
	},
})

Translate("deDE", "master-mathias-shaw", {
	title = "Meister Mathias Shaw",
	subtitle = "Meister von SI:7",
	found = "Die Kaserne der Altstadt",
	hint = "Findet den Meister von SI:7 in der Kaserne der Altstadt.",
	allegiance = "Königreich Stormwind · SI:7",
	aliases = { "Mathias Shaw", "Shaw" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Meister Mathias Shaw führt {link:si-7}SI:7{/link}, den Geheimdienst von {link:stormwind-city}Stormwind{/link}. Von der Kaserne der {link:old-town}Altstadt{/link} aus sammelt er Berichte aus dem ganzen Königreich, bildet Agenten in den Künsten der Heimlichkeit aus und schickt sie dorthin, wohin Soldaten nicht gehen können. Die meisten Bürger von Stormwind kennen seinen Namen nicht. Die meisten seiner Feinde wünschten, sie kennten ihn nicht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Da die Armee fern ist, sind Shaws Agenten die Augen des Königreichs. Sie beobachten die {link:defias-brotherhood}Bruderschaft der Defias{/link} in {link:westfall}Westfall{/link} und im {link:duskwood}Dämmerwald{/link}, und sie beobachten den Hof in der {link:stormwind-keep}Burg Stormwind{/link}. Shaw ist es, der erfährt, dass die Hand der Bruderschaft weiter reicht als bis zu den Feldern und den Minen, bis in die Hallen des eigenen Adels des Königreichs.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lenkt die Agenten von {link:si-7}SI:7{/link} gegen die {link:defias-brotherhood}Defias{/link} in {link:westfall}Westfall{/link} und im {link:duskwood}Dämmerwald{/link}.
• Er bildet die Schurken von {link:stormwind-city}Stormwind{/link} aus.
• Er deckt den Verräter {link:gregor-lescovar}Lord Gregor Lescovar{/link} auf.]=],
		},
	},
	chapters = {
		{
			title = "Schatten der Vergangenheit",
			hint = [=[Bringt dem Meister von SI:7 die Beschreibung von Bazil Thredds Besucher.]=],
			text = [=[Vor dem Aufstand im {link:the-stockade}Verlies{/link} hatte {link:bazil-thredd}Bazil Thredd{/link} einen Besucher. Der Aufseher schrieb nieder, was er von diesem Besucher sah, und versiegelte es. Die Beschreibung ging durch die Hände von {link:baros-alexston}Baros Alexston{/link} und kam zu Shaw. Er las sie, und er wusste, dass die Spur nach {link:stormwind-city}Stormwind{/link} selbst zurückführte. Er sandte Nachricht an einen alten Freund, der die Stadt beobachtet.]=],
		},
		{
			title = "Der Kopf der Bestie",
			hint = "Helft SI:7, den Verräter bei Hofe zu entlarven.",
			text = [=[Als der Verräter Lord {link:gregor-lescovar}Lescovar{/link} und sein Kontaktmann der {link:defias-brotherhood}Defias{/link} tot im königlichen Garten lagen, erreichte die Nachricht Shaw. Es war ein Sieg, aber kein Ende. Ein Lord des Hauses der Adligen hatte mit VanCleefs Bruderschaft zusammengearbeitet, und Shaw sandte den ganzen Bericht an den Stadtarchitekten, damit er den König erreiche.]=],
		},
	},
	mentions = {
		{ text = "Die {link:defias-brotherhood}Bruderschaft der Defias{/link}" },
		{ text = "Die {link:defias-brotherhood}Bruderschaft der Defias{/link}" },
		{ text = "Shadow of the Past" },
		{ text = "Look to an Old Friend" },
		{ text = "The Head of the Beast" },
		{ text = "Brotherhood's End" },
		{ text = "Seek out SI: 7" },
		{ text = "The First and the Last" },
		{ text = "Honor the Dead" },
	},
	bonds = {
		{ id = "elling-trias", name = "Elling Trias", note = "sein Agent im Handelsdistrikt" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "teilt seinen Kampf gegen die Defias" },
		{ id = "gregor-lescovar", name = "Gregor Lescovar", note = "der Verräter, den er entlarvte" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "der Regent, dem er dient" },
	},
})

Translate("deDE", "baros-alexston", {
	title = "Baros Alexston",
	subtitle = "Stadtarchitekt von Stormwind",
	found = "Das Rathaus, Kathedralenplatz",
	hint = "Findet den Stadtarchitekten im Rathaus am Kathedralenplatz.",
	allegiance = "Königreich Stormwind · Rathaus",
	aliases = { "Baros", "Alexston" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Baros Alexston ist der Stadtarchitekt von {link:stormwind-city}Stormwind{/link}. Vom Rathaus am {link:cathedral-square}Kathedralenplatz{/link} aus überwacht er den Bau und die Instandhaltung der {link:capital-city}Hauptstadt{/link}. Er kennt die Steine von Stormwind besser als jeder Lord des Hofes, und er kennt den Preis, der gezahlt wurde, um sie aufzurichten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Baros steht am Kreuzungspunkt von Stormwinds ältester Wunde. Die Stadt, die er pflegt, wurde von den Steinmetzen wieder aufgebaut, die zur {link:defias-brotherhood}Bruderschaft der Defias{/link} wurden. Als {link:edwin-vancleef}Edwin VanCleef{/link} einen Brief schrieb, den er nie abschickte, war er an Baros gerichtet. Durch den Architekten gelangt die Geschichte der Bruderschaft von den {link:the-deadmines}Todesminen{/link} ins {link:the-stockade}Verlies{/link}, von {link:si-7}SI:7{/link} in den Thronsaal.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält die Gebäude von {link:stormwind-city}Stormwind{/link} instand.
• Er handelt nach VanCleefs Brief und sendet Nachricht an den Aufseher des Verlieses.
• Er trägt den Kampf gegen die Bruderschaft zu {link:si-7}SI:7{/link} und an den Hof.
• Er beantwortet, so gut er kann, die Bitten, die die Stadt von fernen Küsten erreichen.]=],
		},
	},
	chapters = {
		{
			title = "Bescheidene Anfänge",
			hint = [=[Holt den alten Kompass des Architekten aus seinem Haus in Westfall.]=],
			text = [=[Baros hatte einst ein Haus in {link:westfall}Westfall{/link}. Er ließ dort etwas zurück: einen alten Kompass, das Werkzeug seines ersten Handwerks. Westfall ist jetzt gefährlich, und seine Höfe sind Dieben und dem Verfall anheimgefallen. Doch ein Baumeister vergisst das Instrument nicht, das ihn zuerst lehrte, eine gerade Linie zu ziehen.]=],
		},
		{
			title = "Der nie abgeschickte Brief",
			hint = [=[Bringt dem Architekten den Brief, der unter VanCleefs Habe gefunden wurde.]=],
			text = [=[{link:edwin-vancleef}Edwin VanCleef{/link} hatte einen Brief an Baros geschrieben und versiegelt, doch er verließ die {link:the-deadmines}Todesminen{/link} nie. Als er endlich in die Hände des Architekten gelangte, las er ihn mit Sorgfalt. Seine Worte lenkten seine Gedanken zum {link:the-stockade}Verlies{/link}, wo einer von VanCleefs Leutnants, {link:bazil-thredd}Bazil Thredd{/link}, gefangen gehalten wurde.]=],
		},
		{
			title = "Ein Brief aus Auberdine",
			hint = [=[Tragt den Brief des Ältesten von Auberdine über das Meer nach Stormwind.]=],
			text = [=[Der Älteste {link:thundris-windweaver}Thundris Windweaver{/link} aus {link:auberdine}Auberdine{/link} schrieb Baros und bat darum, dass man seine kleine Stadt nicht vergesse. Baros lachte, als der Überbringer des Briefes eintraf, und sein Lächeln verblasste, während er las. Seine Antwort war ehrlich. Die Schatzkammern von {link:stormwind-city}Stormwind{/link} sind nicht mehr, was sie waren, und was übrig ist, ist dünn verteilt. Er hatte nichts zu senden als sein Bedauern.]=],
		},
	},
	mentions = {
		{ text = "Humble Beginnings" },
		{ text = "The Unsent Letter" },
		{ text = "{link:bazil-thredd}Bazil Thredd{/link}" },
		{ text = "The Curious Visitor" },
