		{ text = "Brotherhood's End" },
		{ text = "An Audience with the King" },
		{ text = "Expanding Horizons" },
		{ text = "Making Do" },
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "schrieb ihm einen Brief, der nie abgeschickt wurde" },
		{ id = "warden-thelwater", name = "Aufseher Thelwater", note = "hütet das Verlies" },
		{ id = "master-mathias-shaw", name = "Meister Mathias Shaw", note = "Meister von SI:7" },
