})

Translate("deDE", "grayson-shadowbreaker", {
	title = "Grayson Shadowbreaker",
	subtitle = "Lord der Paladine der Kathedrale",
	found = "Die Kathedrale des Lichts, Kathedralenplatz",
	hint = [=[Sucht den Lord, der in der Kathedrale des Lichts Paladine ausbildet.]=],
	allegiance = "Kirche des Heiligen Lichts · Paladine von Stormwind",
	aliases = { "Lord Grayson Shadowbreaker", "Shadowbreaker" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lord Grayson Shadowbreaker bildet die Paladine von {link:stormwind-city}Stormwind{/link} in den Hallen der {link:cathedral-of-light}Kathedrale des Lichts{/link} aus. Er ist Ritter und Lehrer, und seine Schüler lernen von ihm, dass das Heilige Licht Opfer verlangt, bevor es Stärke gewährt. Die jungen Paladine des Königreichs gehen durch seine Hände, und ebenso die alten, wenn sie einen härteren Weg suchen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:captain-grayson}Grayson{/link} hält den Bund von Glauben und Stahl lebendig, den die Kirche des {link:holy-light}Heiligen Lichts{/link} nach dem Ersten Krieg schmiedete. Sein Rat reicht über {link:stormwind-city}Stormwind{/link} hinaus. Er schickt junge Paladine der {link:dwarves}Zwerge{/link} zu ihren eigenen Lehrern in {link:ironforge}Ironforge{/link}, und ihm werden heilige Dinge anvertraut, die das Königreich sicher verwahren will.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bildet die Paladine der Kathedrale aus.
• Er schickt zwergische Paladine zu Tiza Battleforge in {link:ironforge}Ironforge{/link}.
• Er führt die bewährten Paladine des Reiches auf einen langen Weg der Prüfungen und Opfer.
• Er nimmt die Statuette der Menethils zur Verwahrung in der Kathedrale entgegen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Graysons Leben vor der Kathedrale geschrieben oder über die Taten, die ihm seinen Titel einbrachten.]=],
		},
	},
	chapters = {
		{
			title = "Eine Reliquie von Terenas",
			hint = [=[Bringt eine kleine Statue des alten Königs von Lordaeron zur Kathedrale.]=],
			text = [=[König {link:terenas-menethil}Terenas Menethil{/link} war ein bescheidener Mann, der Denkmäler nicht mochte, und wenige Abbilder von ihm überstanden den Fall seines Königreichs. Als eine kleine Statue von ihm aus dem {link:wetlands}Sumpfland{/link} kam, schien das Licht in ihr zu ruhen. Sie wurde nach {link:stormwind-city}Stormwind{/link} getragen und in Lord Graysons Obhut gegeben, um in der {link:cathedral-of-light}Kathedrale des Lichts{/link} bewacht zu werden.]=],
		},
		{
			title = "Der Weg des Opfers",
			hint = [=[Geht den langen Weg, den Lord Grayson den Paladinen des Reiches vorgibt.]=],
			text = [=[{link:captain-grayson}Grayson{/link} verleiht die Ehren eines Paladins nicht leichtfertig. Die erste Prüfung, die er stellt, ist eine des Opfers: eine kostbare Gabe an die Kirche von {link:ironforge}Ironforge{/link}, im Tausch gegen ein heiliges Räuchergefäß, das ihr Hohepriester verwahrt.]=],
		},
	},
	mentions = {
		{ text = "Tome of Divinity" },
		{ text = "Emphasis on Sacrifice" },
		{ text = "Lord Grayson Shadowbreaker" },
		{ text = "A Friend of the Family" },
	},
	bonds = {
		{ id = "archbishop-benedictus", name = "Erzbischof Benedictus", note = "führt die Kirche, der er dient" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "ein Mitstreiter des Lichts" },
	},
})

